/**
 * The contract `calendar.tsx` (native) and `calendar.web.tsx` (react-day-picker)
 * both implement. Its own module because Metro resolves `./calendar` to
 * `calendar.web.tsx` on web.
 *
 * `mode` was originally left out, on the grounds that range selection had no
 * native implementation behind it and a prop that works on one platform is a
 * promise half-kept. It is in now because the implementation is in: `calendar.tsx`
 * draws and selects ranges itself. `DateRange` and `DateMatcher` are declared here
 * rather than imported from react-day-picker for the same reason — a shared type
 * cannot come from a library only one platform has.
 */

/** A start and an end. `to` is absent while the range is half-picked. */
export type DateRange = {
  from: Date | undefined;
  to?: Date | undefined;
};

/**
 * Which days a matcher covers. A subset of react-day-picker's, kept to the forms
 * that can be evaluated without the library: a day, a list of days, a closed
 * interval, an open one, or a predicate. `dayOfWeek` and the rest are not here
 * because nothing in this registry asks for them yet.
 */
export type DateMatcher =
  | Date
  | Date[]
  | { from: Date; to: Date }
  | { before: Date }
  | { after: Date }
  | ((date: Date) => boolean);

type CalendarSharedProps = {
  /** Days that cannot be chosen. Several matchers are ORed. */
  disabled?: DateMatcher | DateMatcher[] | undefined;
  /** Month shown on first render; defaults to the selected date's month. */
  defaultMonth?: Date | undefined;
  /** How many months to show at once. Defaults to 1. */
  numberOfMonths?: number | undefined;
  /** The earliest month the caller can navigate back to. */
  startMonth?: Date | undefined;
  /** 0 is Sunday. Defaults to 0. */
  weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6 | undefined;
  className?: string | undefined;
};

/**
 * Discriminated on `mode`, so `onSelect` is handed a `Date` under `"single"` and a
 * `DateRange` under `"range"` — a range calendar wired to a `Date` field is a type
 * error at the call site rather than a runtime surprise.
 */
export type CalendarProps =
  | (CalendarSharedProps & {
      mode?: "single" | undefined;
      selected?: Date | undefined;
      onSelect: (date: Date | undefined) => void;
    })
  | (CalendarSharedProps & {
      mode: "range";
      selected?: DateRange | undefined;
      onSelect: (range: DateRange | undefined) => void;
    });

/**
 * The native calendar: month grids built from date-fns.
 *
 * Written out rather than pulling in a native calendar library: the surface is
 * month navigation, single and range selection, and disabled days, and a calendar
 * library brings its own theming system that would sit outside the tailwind tokens
 * every other primitive follows.
 *
 * `calendar.web.tsx` is react-day-picker; `calendar-base.ts` holds the contract.
 * The matcher evaluation here is this file's own, because react-day-picker's lives
 * inside react-day-picker.
 */
import {
  addMonths,
  eachDayOfInterval,
  endOfMonth,
  endOfWeek,
  format,
  isAfter,
  isBefore,
  isSameDay,
  isSameMonth,
  startOfMonth,
  startOfWeek,
} from "date-fns";
import { useState } from "react";
import { Pressable, Text, View } from "react-native";
import type { CalendarProps, DateMatcher, DateRange } from "@/components/ui/calendar-base";
import { ChevronLeft, ChevronRight } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

const WEEKDAYS = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

/** Whether one matcher covers a day. Several are ORed by the caller below. */
function covers(day: Date, matcher: DateMatcher): boolean {
  if (typeof matcher === "function") return matcher(day);
  if (matcher instanceof Date) return isSameDay(day, matcher);
  if (Array.isArray(matcher)) return matcher.some((d) => isSameDay(day, d));
  if ("from" in matcher) {
    return !isBefore(day, startOfDay(matcher.from)) && !isAfter(day, endOfDay(matcher.to));
  }
  if ("before" in matcher) return isBefore(day, startOfDay(matcher.before));
  return isAfter(day, endOfDay(matcher.after));
}

// Comparisons are between calendar days, not instants: `{ before: new Date() }`
// means "before today", and a matcher built at 14:00 must not disable this morning.
function startOfDay(date: Date): Date {
  const out = new Date(date);
  out.setHours(0, 0, 0, 0);
  return out;
}
function endOfDay(date: Date): Date {
  const out = new Date(date);
  out.setHours(23, 59, 59, 999);
  return out;
}

function isDisabled(day: Date, disabled: CalendarProps["disabled"]): boolean {
  if (!disabled) return false;
  // A bare `Date[]` is one matcher, not a list of them — `covers` handles it — so the
  // list case is only reached for a genuine array of matchers.
  if (Array.isArray(disabled) && disabled.some((m) => !(m instanceof Date))) {
    return (disabled as DateMatcher[]).some((m) => covers(day, m));
  }
  return covers(day, disabled as DateMatcher);
}

/** Where a day sits in the selection, which is what decides how it is drawn. */
function placeInRange(day: Date, range: DateRange | undefined) {
  if (!range?.from) return { selected: false, edge: false, middle: false };
  const from = range.from;
  const to = range.to;
  if (!to) return { selected: isSameDay(day, from), edge: isSameDay(day, from), middle: false };
  const edge = isSameDay(day, from) || isSameDay(day, to);
  const inside = !isBefore(day, startOfDay(from)) && !isAfter(day, endOfDay(to));
  return { selected: inside, edge, middle: inside && !edge };
}

/**
 * The next range for a press, matching react-day-picker's behaviour: the first press
 * starts a range, the second closes it, and a press before the start restarts rather
 * than producing a backwards range.
 */
function nextRange(day: Date, current: DateRange | undefined): DateRange {
  if (!current?.from || current.to) return { from: day, to: undefined };
  if (isBefore(day, current.from)) return { from: day, to: undefined };
  return { from: current.from, to: day };
}

export function Calendar(props: CalendarProps) {
  const {
    disabled,
    defaultMonth,
    numberOfMonths = 1,
    startMonth,
    weekStartsOn = 0,
    className,
  } = props;

  const firstMonth =
    defaultMonth ?? (props.mode === "range" ? props.selected?.from : props.selected) ?? new Date();
  const [month, setMonth] = useState(() => startOfMonth(firstMonth));

  const canGoBack = !startMonth || isAfter(month, startOfMonth(startMonth));
  const months = Array.from({ length: Math.max(1, numberOfMonths) }, (_, i) => addMonths(month, i));
  const weekdays = [...WEEKDAYS.slice(weekStartsOn), ...WEEKDAYS.slice(0, weekStartsOn)];

  const press = (day: Date) => {
    if (props.mode === "range") props.onSelect(nextRange(day, props.selected));
    else props.onSelect(day);
  };

  return (
    <View className={cn("p-3", className)}>
      <View className="mb-2 flex-row items-center justify-between">
        <Pressable
          onPress={() => setMonth(addMonths(month, -1))}
          disabled={!canGoBack}
          aria-label="Previous month"
          className={cn("p-1", !canGoBack && "opacity-30")}
        >
          <ChevronLeft className="h-4 w-4 text-foreground" />
        </Pressable>
        <Text className="text-sm font-medium text-foreground">
          {months.length === 1
            ? format(month, "MMMM yyyy")
            : `${format(month, "MMM yyyy")} – ${format(months[months.length - 1] ?? month, "MMM yyyy")}`}
        </Text>
        <Pressable
          onPress={() => setMonth(addMonths(month, 1))}
          aria-label="Next month"
          className="p-1"
        >
          <ChevronRight className="h-4 w-4 text-foreground" />
        </Pressable>
      </View>

      {months.map((shown) => (
        <View key={shown.toISOString()}>
          {months.length > 1 ? (
            <Text className="mb-1 text-center text-xs font-medium text-foreground">
              {format(shown, "MMMM yyyy")}
            </Text>
          ) : null}

          <View className="flex-row">
            {weekdays.map((day) => (
              <Text key={day} className="flex-1 text-center text-xs text-muted-foreground">
                {day}
              </Text>
            ))}
          </View>

          <View className="flex-row flex-wrap">
            {/* Padded out to whole weeks so every row has seven cells and the grid
                does not reflow as the month changes. */}
            {eachDayOfInterval({
              start: startOfWeek(startOfMonth(shown), { weekStartsOn }),
              end: endOfWeek(endOfMonth(shown), { weekStartsOn }),
            }).map((day) => {
              const place =
                props.mode === "range"
                  ? placeInRange(day, props.selected)
                  : {
                      selected: props.selected ? isSameDay(day, props.selected) : false,
                      edge: props.selected ? isSameDay(day, props.selected) : false,
                      middle: false,
                    };
              const off = isDisabled(day, disabled);
              return (
                <Pressable
                  key={day.toISOString()}
                  onPress={() => press(day)}
                  disabled={off}
                  aria-disabled={off}
                  aria-selected={place.selected}
                  className={cn(
                    "h-9 items-center justify-center",
                    // A range's interior is a continuous band, so only its ends are
                    // rounded — the same shape react-day-picker draws.
                    place.middle ? "bg-accent" : "rounded-md",
                    place.edge && "bg-primary",
                    off && "opacity-30",
                  )}
                  // Seven per row, and `flex-wrap` needs a width it can measure.
                  // A `w-[14.2857%]` class would round to the same place; the style
                  // keeps the arithmetic visible.
                  style={{ width: `${100 / 7}%` }}
                >
                  <Text
                    className={cn(
                      "text-sm",
                      place.edge
                        ? "text-primary-foreground"
                        : place.middle
                          ? "text-accent-foreground"
                          : isSameMonth(day, shown)
                            ? "text-foreground"
                            : "text-muted-foreground",
                    )}
                  >
                    {format(day, "d")}
                  </Text>
                </Pressable>
              );
            })}
          </View>
        </View>
      ))}
    </View>
  );
}

/**
 * The web calendar: react-day-picker, using the library's own stylesheet so we
 * do not have to track its evolving `classNames` API across versions.
 * `calendar.tsx` is the native counterpart; `calendar-base.ts` holds the
 * contract they share.
 *
 * The contract's `DateMatcher` and `DateRange` are structurally react-day-picker's
 * own, which is why the two `mode` branches pass straight through — the types are
 * declared in `calendar-base.ts` rather than imported so the native half can share
 * them, not because they differ.
 *
 * It also takes the rest of react-day-picker's props — `captionLayout`,
 * `showOutsideDays`, `classNames`, `components`, `formatters`, `locale` — as
 * shadcn's `calendar` does, and hands them to `DayPicker` unchanged. Those
 * extras are web only.
 */
import { DayPicker, type PropsBase } from "react-day-picker";
import type { CalendarProps } from "@/components/ui/calendar-base";
import { cn } from "@/lib/utils";
import "react-day-picker/style.css";

/** What `DayPicker` takes beyond the shared contract, passed through as it is. */
type DayPickerExtras = Omit<
  PropsBase,
  | "disabled"
  | "defaultMonth"
  | "numberOfMonths"
  | "startMonth"
  | "weekStartsOn"
  | "className"
  | "mode"
  | "selected"
  | "onSelect"
  | "required"
>;

export function Calendar(props: CalendarProps & DayPickerExtras) {
  const {
    mode: _mode,
    selected: _selected,
    onSelect: _onSelect,
    disabled,
    defaultMonth,
    numberOfMonths,
    startMonth,
    weekStartsOn,
    className,
    ...extras
  } = props;

  // Spread rather than passed: under `exactOptionalPropertyTypes` an explicit
  // `undefined` is not the same as an absent prop, and react-day-picker reads
  // several of these as "the caller set this".
  const shared = {
    ...extras,
    ...(disabled === undefined ? {} : { disabled }),
    ...(defaultMonth === undefined ? {} : { defaultMonth }),
    ...(numberOfMonths === undefined ? {} : { numberOfMonths }),
    ...(startMonth === undefined ? {} : { startMonth }),
    ...(weekStartsOn === undefined ? {} : { weekStartsOn }),
    className: cn("p-3", className),
  };

  if (props.mode === "range") {
    return (
      <DayPicker
        mode="range"
        {...shared}
        {...(props.selected === undefined ? {} : { selected: props.selected })}
        onSelect={props.onSelect}
      />
    );
  }

  return (
    <DayPicker
      mode="single"
      {...shared}
      {...(props.selected === undefined ? {} : { selected: props.selected })}
      onSelect={props.onSelect}
    />
  );
}
